use serde_json::{json,Value};
use ubu_core::{AdvisoryCandidate,AuthoritySource,ObjectType,UbuId,UbuTimestamp,VersionRef,worker::{AdvisoryTransport,LocalAdvisorySubmission,LocalAdvisoryResult,LocalAdvisoryResultStatus}};
use ubu_orchestrator::{config::ServerConfig,state::AppState,planning_time::FixedClock,services::{precondition_review as review,advisory_service}};
use ubu_store::models::object_record::NewObjectRecord;
use std::path::Path;
use sqlx::Row;
struct Stub {candidate:AdvisoryCandidate}
impl AdvisoryTransport for Stub {
 fn submit(&self,sub:&LocalAdvisorySubmission)->ubu_core::Result<LocalAdvisoryResult>{
  Ok(LocalAdvisoryResult{submission_id:sub.submission_id.clone(),authority:sub.authority.clone(),provider_config:sub.provider_config.clone(),observed_policy_versions:sub.observed_policy_versions.clone(),input_digests:sub.input_digests.clone(),status:LocalAdvisoryResultStatus::Ok,artifacts:vec![],proposed_candidates:vec![self.candidate.clone()],diagnostics:vec![],telemetry:vec![],deletion_confirmed:None})
 }
}
fn load(root:&Path,name:&str)->Value {serde_json::from_str(&std::fs::read_to_string(root.join(format!("{name}.json"))).unwrap()).unwrap()}
fn save(root:&Path,name:&str,value:&Value) {std::fs::write(root.join(format!("{name}.json")),serde_json::to_string_pretty(value).unwrap()).unwrap()}
async fn count(state:&AppState,table:&str)->i64 {sqlx::query_scalar(&format!("SELECT COUNT(*) FROM {table}")).fetch_one(state.inner().store.pool()).await.unwrap()}
async fn snapshot(state:&AppState)->Vec<(String,Vec<String>)> {
 let pool=state.inner().store.pool();
 let names:Vec<String>=sqlx::query_scalar("SELECT name FROM sqlite_master WHERE type='table' AND name NOT IN ('advisory_candidates','mutation_envelopes','sqlite_sequence') ORDER BY name").fetch_all(pool).await.unwrap();
 let mut output=vec![];
 for name in names {
  let cols=sqlx::query(&format!("PRAGMA table_info(\"{name}\")")).fetch_all(pool).await.unwrap();
  let expr=cols.iter().map(|row|format!("quote(\"{}\")",row.get::<String,_>("name"))).collect::<Vec<_>>().join(" || '|' || ");
  let mut rows:Vec<String>=sqlx::query_scalar(&format!("SELECT {expr} FROM \"{name}\"")).fetch_all(pool).await.unwrap();rows.sort();output.push((name,rows));
 }output
}
async fn run(root:&Path){
 let mut results=serde_json::Map::new();
 for name in ["baseline","inline","unknown","reference","missing","stale"] {
  let now=UbuTimestamp::parse("2026-09-19T09:00:00Z").unwrap();
  let state=AppState::in_memory(ServerConfig::from_env()).await.unwrap().with_clock(FixedClock(now));
  let raw=load(root,name);let c:AdvisoryCandidate=serde_json::from_value(raw.clone()).unwrap();c.validate().unwrap();
  assert_eq!(serde_json::to_value(&c).unwrap(),raw);
  let c:AdvisoryCandidate=serde_json::from_str(&serde_json::to_string(&c).unwrap()).unwrap();assert_eq!(serde_json::to_value(&c).unwrap(),raw);
  let task_id=c.target_refs[0].id.as_str();let existing=raw["normalized_proposal"]["existing_precondition"].clone();
  let task=json!({"id":task_id,"title":"Synthetic carrier probe","description":"Synthetic carrier probe.","status":"active","preconditions":existing,"provenance":{"created_at":now,"authority_source":"user"}});
  let env=state.envelope_for([(UbuId::parse(task_id).unwrap(),VersionRef::Absent)].into_iter().collect(),AuthoritySource::User,now).unwrap();
  ubu_store::queries::admit_object(state.inner().store.pool(),&env,NewObjectRecord{id:task_id.into(),object_type:ObjectType::Task.as_str().into(),version:1,status:"active".into(),compartment_label:"default".into(),payload:task.clone(),created_at:now.to_string(),updated_at:now.to_string()}).await.unwrap();
  let context=review::Context{force:false,tasks:vec![review::ReviewTask{id:task_id.into(),description:"Synthetic carrier probe.".into(),existing_precondition:existing.clone(),existing_words:review::words(&existing),prior_rejection_reason:None}],targets:vec![]};
  let sub=review::submission(&state,&context,"synthetic-carrier-probe").await.unwrap();
  let before=snapshot(&state).await;let ledger_before=count(&state,"mutation_envelopes").await;
  let report=advisory_service::run_advisory(&state,sub,&Stub{candidate:c.clone()}).await.unwrap();
  assert_eq!(report.status,LocalAdvisoryResultStatus::Ok);assert_eq!(report.candidates_stored,1);assert_eq!(report.candidates_rejected,0);assert_eq!(report.candidate_ids,vec![c.advisory_candidate_id.as_str()]);assert_eq!(report.validation_error,None);
  assert_eq!(snapshot(&state).await,before);assert_eq!(count(&state,"mutation_envelopes").await,ledger_before+1);
  let stored=ubu_store::api::review::get_advisory_candidate(state.inner().store.pool(),&c.advisory_candidate_id).await.unwrap().unwrap();
  let normalized=serde_json::to_value(stored.candidate().unwrap()).unwrap();save(root,&format!("{name}-enqueued"),&normalized);
  let mut expected=raw.clone();expected["normalized_proposal"]["blocked_now"]=json!(true);expected["payload"]["value"]=expected["normalized_proposal"].clone();expected["suppression_key"]=json!("review:sha256:57ea73a474832a19855231c2d99b66a4ed30b1eeccc4721fe20933e462ebee96");assert_eq!(normalized,expected);
  if name=="stale" {
   let env=state.envelope_for([(UbuId::parse(task_id).unwrap(),VersionRef::Version(1))].into_iter().collect(),AuthoritySource::User,now).unwrap();let mut changed=task.clone();changed["preconditions"]["expected"]=json!(26);
   ubu_store::queries::admit_object(state.inner().store.pool(),&env,NewObjectRecord{id:task_id.into(),object_type:ObjectType::Task.as_str().into(),version:1,status:"active".into(),compartment_label:"default".into(),payload:changed,created_at:now.to_string(),updated_at:now.to_string()}).await.unwrap();
  }
  let pre_admission=snapshot(&state).await;let pre_ledger=count(&state,"mutation_envelopes").await;
  let outcome=advisory_service::admit_candidate(&state,&c.advisory_candidate_id,1).await;
  if name=="stale" {
   let error=outcome.err().expect("changed precondition rejects");assert_eq!(snapshot(&state).await,pre_admission);assert_eq!(count(&state,"mutation_envelopes").await,pre_ledger);assert_eq!(count(&state,"candidate_decision_events").await,0);
   let current=ubu_store::api::review::get_advisory_candidate(state.inner().store.pool(),&c.advisory_candidate_id).await.unwrap().unwrap();assert_eq!(serde_json::to_value(current.candidate().unwrap()).unwrap(),normalized);
   results.insert(name.into(),json!({"report":report,"admitted":false,"error":error.to_string(),"canonical_rows_unchanged":true,"admission_ledger_delta":0,"decision_events":0}));continue;
  }
  let (admitted,object)=outcome.unwrap();let admitted_json=serde_json::to_value(admitted.candidate().unwrap()).unwrap();let object_json:Value=serde_json::from_str(&object.payload_json).unwrap();
  let mut expected_task=task.clone();expected_task.as_object_mut().unwrap().remove("preconditions");assert_eq!(object_json,expected_task);assert_eq!(object.version,2);
  let mut expected_candidate=normalized.clone();expected_candidate["lifecycle_state"]=json!("admitted");expected_candidate["version"]=json!(2);expected_candidate["links"]["admission_ref"]=json!(task_id);assert_eq!(admitted_json,expected_candidate);
  assert_eq!(count(&state,"candidate_decision_events").await,1);assert_eq!(count(&state,"mutation_envelopes").await,pre_ledger+1);assert_eq!(count(&state,"logs").await,0);
  let event=sqlx::query("SELECT observed_candidate_version,from_state,to_state,resulting_object_id,envelope_json FROM candidate_decision_events").fetch_one(state.inner().store.pool()).await.unwrap();
  let envelope:Value=serde_json::from_str(&event.get::<String,_>("envelope_json")).unwrap();
  let event_json=json!({"observed_candidate_version":event.get::<i64,_>("observed_candidate_version"),"from_state":event.get::<String,_>("from_state"),"to_state":event.get::<String,_>("to_state"),"resulting_object_id":event.get::<String,_>("resulting_object_id"),"envelope":envelope});assert_eq!(event_json["observed_candidate_version"],1);assert_eq!(event_json["to_state"],"admitted");
  save(root,&format!("{name}-admitted"),&admitted_json);save(root,&format!("{name}-task"),&object_json);save(root,&format!("{name}-decision"),&event_json);
  let post=snapshot(&state).await;let changes:Vec<String>=pre_admission.iter().zip(post.iter()).filter(|(a,b)|a!=b).map(|(_,b)|b.0.clone()).collect();
  let after_ledger=count(&state,"mutation_envelopes").await;let duplicate=advisory_service::admit_candidate(&state,&c.advisory_candidate_id,1).await.err().expect("old candidate version rejects");assert_eq!(snapshot(&state).await,post);assert_eq!(count(&state,"mutation_envelopes").await,after_ledger);
  let retrieved=ubu_store::api::review::get_advisory_candidate(state.inner().store.pool(),&c.advisory_candidate_id).await.unwrap().unwrap();assert_eq!(serde_json::to_value(retrieved.candidate().unwrap()).unwrap(),admitted_json);
  results.insert(name.into(),json!({"report":report,"core_roundtrip_equal":true,"enqueued_expected_equal":true,"admitted":true,"candidate_version":2,"task_version":2,"precondition_absent":!object_json.as_object().unwrap().contains_key("preconditions"),"qualifier_member_absent":normalized["payload"]["value"].get("perceptual_qualifiers").is_none(),"evidence_refs":admitted_json["evidence_refs"],"field_provenance":admitted_json["field_provenance"],"admission_ref":admitted_json["links"]["admission_ref"],"decision_events":1,"admission_ledger_delta":1,"log_count":0,"changed_tables":changes,"envelope_observed_versions":event_json["envelope"]["observed_versions"],"repeated_old_version_error":duplicate.to_string(),"repeat_has_no_effect":true}));
 }
 let summary=Value::Object(results);save(root,"results",&summary);println!("{}",serde_json::to_string_pretty(&summary).unwrap());
}
fn main(){let arg=std::env::args().nth(1).unwrap();tokio::runtime::Runtime::new().unwrap().block_on(run(Path::new(&arg)));}

