pub async fn vet_result(
    state: &AppState,
    sub: &LocalAdvisorySubmission,
    result: &mut LocalAdvisoryResult,
) -> Result<()> {
    let context: Context = serde_json::from_value(sub.payload.clone())
        .map_err(|e| AppError::Internal(e.to_string()))?;
    let universe = advisor::current(state).await?;
    let mut accepted = Vec::new();
    let mut seen = std::collections::BTreeSet::new();
    for mut c in std::mem::take(&mut result.proposed_candidates) {
        let target = match c.target_refs.as_slice() {
            [t] if t.object_type == ObjectType::Task => Some(t),
            _ => None,
        };
        let task = target.and_then(|t| context.tasks.iter().find(|task| task.id == t.id.as_str()));
        let valid = is_review(&c)
            && valid_envelope(&c.normalized_proposal)
            && c.confidence.is_none()
            && task.is_some_and(|t| {
                t.existing_precondition == c.normalized_proposal["existing_precondition"]
                    && seen.insert(t.id.clone())
            });
        let missing = if c.normalized_proposal["operation"] == "replace_precondition" {
            advisor::validate_tree(
                &c.normalized_proposal["proposed_precondition"],
                &universe,
                crate::instance_mode::MVP_INSTANCE_MODE,
            )
        } else {
            Ok(Default::default())
        };
        if !valid || missing.is_err() {
            result.status = LocalAdvisoryResultStatus::MalformedResult;
            result.diagnostics = vec![
                json!({"code":"advisory_malformed_result","message":"The model response was not a valid precondition review; no candidates were enqueued"}),
            ];
            return Ok(());
        }
        let task = task.unwrap();
        let row =
            ubu_store::queries::get_current_state(state.inner().store.pool(), &task.id).await?;
        let current: Option<Task> = row
            .map(|r| serde_json::from_str(&r.payload_json))
            .transpose()
            .map_err(|e| AppError::Internal(e.to_string()))?;
        if current.as_ref().is_none_or(|t| {
            t.status != TaskStatus::Active
                || serde_json::to_value(&t.preconditions).ok().as_ref()
                    != Some(&task.existing_precondition)
        }) {
            result.diagnostics.push(json!({"code":"precondition_review_changed","message":"A reviewed Task changed while the review ran; ask again. Nothing was enqueued for it."}));
            continue;
        }
        let missing = missing.unwrap();
        if !missing.is_empty() {
            result
                .diagnostics
                .push(advisor::missing_diagnostic(&task.id, &missing));
            continue;
        }
        let tree = current.unwrap().preconditions.unwrap();
        c.normalized_proposal["blocked_now"] =
            json!(evaluate_universe_precondition(&universe, &tree).is_ok_and(|v| !v));
        c.payload = CandidatePayload::Inline(c.normalized_proposal.clone());
        c.suppression_key = Some(super::review_policy::subject_key(
            &task.id,
            &task.existing_precondition,
        ));
        accepted.push(c);
    }
    result.proposed_candidates = accepted;
    Ok(())
}

/// Each model call sees exactly one Task. The run's timeout and size budget
/// still cover the whole selection; validate every result before any enqueue.
pub fn submit_reviews<T: ubu_core::worker::AdvisoryTransport + ?Sized>(
    sub: &LocalAdvisorySubmission,
    transport: &T,
) -> LocalAdvisoryResult {
    let context: Context = match serde_json::from_value(sub.payload.clone()) {
        Ok(c) => c,
    observed_version: u64,
    answers: &std::collections::BTreeMap<String, String>,
) -> Result<PreparedAdmission> {
    prepare(state, id, observed_version, |candidate, target| {
        apply_clarification(candidate, target, answers)
    })
    .await
}

async fn prepare(
    state: &AppState,
    id: &AdvisoryCandidateId,
    observed_version: u64,
    apply: impl FnOnce(&ubu_core::AdvisoryCandidate, &ObjectRecord) -> Result<NewObjectRecord>,
) -> Result<PreparedAdmission> {
    let candidate = reviewed_candidate(state, id, observed_version).await?;
    let target_ref = proposal_target(&candidate)?;
    let target =
        ubu_store::queries::get_current_state(state.inner().store.pool(), target_ref.id.as_str())
            .await?
            .ok_or_else(|| AppError::TargetNotFound {
                id: target_ref.id.to_string(),
            })?;
    let mut universe_observation = None;
    if candidate.candidate_kind == ubu_core::CandidateKind::Precondition && candidate.normalized_proposal["operation"] != "clear_precondition" {
        let current = super::planning_service::read_current_universe_state(state.inner().store.pool()).await?;
        let Some((universe, version)) = current else {
            return Err(AppError::conflict_diagnostic("advisory_precondition_stale", "The proposal no longer has recorded facts; nothing was admitted"));
        };
        let proposed = if candidate.normalized_proposal["operation"] == "replace_precondition" { &candidate.normalized_proposal["proposed_precondition"] } else { super::precondition_advisor::proposal_trees(&candidate.normalized_proposal)?.0 };
        let missing = super::precondition_advisor::validate_tree(proposed, &universe, crate::instance_mode::MVP_INSTANCE_MODE)
            .map_err(|_| AppError::bad_request_diagnostic("advisory_precondition_invalid", "The proposed precondition cannot be evaluated in this instance"))?;
        if !missing.is_empty() {
            return Err(AppError::conflict_diagnostic("advisory_precondition_stale", "A target required by this proposal is no longer recorded; nothing was admitted"));
        }
        universe_observation = Some((universe.id, VersionRef::Version(u64::try_from(version).map_err(|_| AppError::Internal("invalid UniverseState version".into()))?)));
    }
    let mut record = apply(&candidate, &target)?;
    let version = u64::try_from(target.version)
        .map_err(|_| AppError::Internal("target has an invalid store version".into()))?;
    let mut observations = std::collections::BTreeMap::from([(target_ref.id.clone(), VersionRef::Version(version))]);
    observations.extend(universe_observation);
    let envelope = state.envelope_for(
        observations,
        AuthoritySource::User,
        UbuTimestamp::now_utc(),
    )?;
    record.updated_at = envelope.recorded_time.to_string();
    Ok(PreparedAdmission { envelope, record })
}

impl PreparedAdmission {
    async fn commit(
        self,
        state: &AppState,
        id: &AdvisoryCandidateId,
        observed_version: u64,
    ) -> Result<(CandidateRecord, ObjectRecord)> {
        Ok(admit_advisory_candidate(
            state.inner().store.pool(),
            &self.envelope,
            id,
            observed_version,
            self.record,
        )
        .await?)
    }
}

